#pragma once
static void arrowStyleCheck(const std::string& dir){
    auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(std::string("arrow style audit: ")+why);};
    size_t cases=0,hollow=0,half=0;Session gallery;gallery.doc.setDefaultFont("Arial");gallery.doc.setDefaultTextSize(7);studioio::Page page;page.width=640;page.height=1240;page.x=page.y=0;page.store(gallery.doc);
    for(size_t i=0;i<arrows::arrowPresetCount();++i){const auto& spec=arrows::arrowPresets()[i];
        for(int tier=0;tier<5;++tier)for(double angle:{0.,90.,135.,180.})for(double width:{.6,1.2}){
            auto p=arrows::withHeadTier(arrows::resolvePreset(spec.presetId,Vec2(20,30),Vec2(20,30)+core::direction(angle)*100,width),tier);if(p.presetId==49||p.presetId==57){p.mechanism=true;p.head.length=3.2;p.head.width=2.24;}
            arrows::ArrowGeometry g;require(arrows::buildArrowGeometry(p,width,arrows::Tessellation(),&g).ok()&&g.valid,"every preset builds finite geometry");
            for(const auto& line:g.shafts)for(auto q:line)require(q.finite(),"finite shaft points");for(const auto& h:g.heads){for(auto q:h.outline)require(q.finite(),"finite head outline");for(auto q:h.strokes)require(q.finite(),"finite open head");}
            if(p.family==arrows::ArrowFamily::Arc&&p.shafts==arrows::ShaftCount::Double){require(g.shafts.size()==2&&g.heads.size()==2,"each double arc has its own arrowhead");for(size_t k=0;k<2;++k){const auto& head=g.heads[k];auto join=head.filled&&!g.hollow&&head.outline.size()==4?head.outline[2]:(head.outline[1]+head.outline[head.outline.size()==4?3:2])*.5;const auto& line=g.shafts[k];require(std::min(length(join-line.front()),length(join-line.back()))<1e-6,"double-arc heads meet their own shafts");}}
            if(p.head.shape==arrows::ArrowHeadShape::Cross){require(g.markers.size()==2,"cross has two diagonals");auto axis=core::direction(angle),normal=Vec2(-axis.y,axis.x);for(const auto& stroke:g.markers){auto d=stroke.back()-stroke.front();require(std::abs(dot(d,axis))>.1&&std::abs(dot(d,normal))>.1,"no-go cross is an X rather than a plus");}}
            if(!arrows::isMechanismArrow(p)&&p.shafts==arrows::ShaftCount::One){
                for(const auto& head:g.heads)if(head.outline.size()>=3){auto axis=core::direction(head.angleDeg);bool begin=length(head.tip-p.begin)<1e-7;const auto& line=g.shafts.front();if(line.empty())continue;auto end=begin?line.front():line.back();
                    if(g.hollow||!head.filled){double base=dot(head.tip-head.outline[1],axis);require(dot(head.tip-end,axis)>=base-1e-6,"hollow shaft stops outside the triangle interior");++hollow;}
                    if(head.filled&&(p.head.sides==arrows::HeadSides::Left||p.head.sides==arrows::HeadSides::Right)){require(dot(head.tip-end,axis)>p.head.length*.4,"filled half arrow has no shaft stub at its tip");for(auto q:head.outline)require(dot(q-head.tip,axis)<1e-6,"half head points in direction of travel");++half;}
                }
            }++cases;
        }
        auto p=arrows::withHeadTier(arrows::resolvePreset(spec.presetId,Vec2(0,0),Vec2(90,0),.6),2);if(p.presetId==49||p.presetId==57){p.mechanism=true;p.head.length=3.2;p.head.width=2.24;}arrows::ArrowGeometry g;arrows::buildArrowGeometry(p,.6,arrows::Tessellation(),&g);
        double scale=std::min(126/std::max(1.,g.bounds.width()),54/std::max(1.,g.bounds.height()));auto center=(g.bounds.min+g.bounds.max)*.5;Vec2 cell(20+(i%4)*155,20+(i/4)*80),offset=cell+Vec2(65,45)-center*scale;
        p.begin=p.begin*scale+offset;p.end=p.end*scale+offset;p.arcSagitta*=scale;p.head.length*=scale;p.head.width*=scale;p.separation*=scale;p.strokeWidth=.6;ObjectId id;require(arrows::addArrow(gallery.doc,p,.6,&id).ok(),"gallery object");gallery.doc.addText(cell,6,std::to_string(spec.presetId)+"  "+spec.displayName,&id);
    }
    require(cases==arrows::arrowPresetCount()*40&&hollow>0&&half>0,"all style, size, direction and width combinations covered");gallery.refresh();require(gallery.save(dir+"/all-arrow-styles.cdxml",true).ok(),"save gallery");Session reopened;require(reopened.open(dir+"/all-arrow-styles.cdxml").ok(),"reopen gallery");size_t count=0;for(const auto& a:reopened.doc.arrows().records())if(a.isAlive())++count;require(count==arrows::arrowPresetCount(),"no missing or duplicate styles on reopen");
    Session detail;detail.doc.setDefaultFont("Arial");detail.doc.setDefaultTextSize(8);studioio::Page paper;paper.width=240;paper.height=500;paper.x=paper.y=0;paper.store(detail.doc);int row=0;
    for(uint32_t id:{32u,11u,12u,8u,9u,14u,15u,40u,38u}){auto p=arrows::withHeadTier(arrows::resolvePreset(id,Vec2(35,40+row*48),Vec2(195,40+row*48),.6),3);ObjectId object;detail.doc.addText(Vec2(35,22+row*48),8,std::to_string(id)+"  "+arrows::presetById(id)->displayName,&object);arrows::addArrow(detail.doc,p,.6,&object);++row;}detail.refresh();require(detail.save(dir+"/corrected-arrow-styles.cdxml",true).ok(),"save detail comparison");
    for(double angle:{180.,-180.}){
        std::string data="<CDXML BondLength='14.4' LineWidth='0.6'><page id='1'><arrow id='2' Tail3D='0 0 0' Head3D='100 0 0' Center3D='50 0 0' MajorAxisEnd3D='100 0 0' MinorAxisEnd3D='50 50 0' AngularSize='"+std::to_string(angle)+"' ArrowheadHead='Full' ArrowheadTail='None' ArrowheadType='Solid' HeadSize='1500' ArrowheadWidth='375'/></page></CDXML>";
        auto file=dir+(angle>0?"/public-positive-180.cdxml":"/public-negative-180.cdxml");std::ofstream(file)<<data;Session imported;require(imported.open(file).ok(),"public semicircle import");double low=1e100,high=-1e100;for(const auto& primitive:imported.scene.primitives())if(primitive.source.kind==ObjectKind::Arrow)for(auto point:primitive.points){low=std::min(low,point.y);high=std::max(high,point.y);}require(angle>0?high>45:low< -45,"public semicircle keeps its signed side");
    }
    {auto file=dir+"/public-no-go.cdxml";std::ofstream(file)<<"<CDXML LineWidth='0.6'><page id='1'><arrow id='2' Tail3D='0 0 0' Head3D='100 0 0' ArrowheadHead='Full' ArrowheadTail='None' ArrowheadType='Solid' NoGo='Cross' HeadSize='1500' ArrowheadWidth='375'/></page></CDXML>";Session imported;require(imported.open(file).ok(),"public no-go import");arrows::ArrowParams p;bool ok=false;require(arrows::readArrow(imported.doc,imported.doc.arrows().records().back().id,&p,&ok).ok()&&ok&&p.head.atEnd,"public no-go preserves its explicit arrowhead");}
    std::ofstream(dir+"/arrow-style-audit.json")<<"{\"presets\":"<<arrows::arrowPresetCount()<<",\"geometry_cases\":"<<cases<<",\"size_tiers\":5,\"directions\":4,\"line_widths\":2,\"hollow_cases\":"<<hollow<<",\"half_head_cases\":"<<half<<",\"finite_geometry\":true,\"hollow_interior_clear\":true,\"half_head_tip_clear\":true,\"cdxml_round_trip\":true}";
}
